    priceProxy: r.year === 2021 ? 10.52 : r.year === 2022 ? 11.35 : r.year === 2023 ? 12.54 : r.year === 2024 ? 13.9 : 14.5,
  }));
}

export function corridorRadar() {
  return CORRIDORS.map((c) => ({
    corridor: `${c.from.split(" ")[0]}???${c.to.split(" ")[0]}`,
    intensity: c.intensity,
    kind: c.kind,
  }));
}

