import {
  CORRIDORS,
  HEADLINE,
  REGION_DEMAND,
  SINGAPORE_PARTNERS,
  SOURCE_NOTE,
  US_END_USE,
  dependenceScatter,
  extractorBars,
  fmtMt,
  fmtPct,
  importerBars,
  regionHhi,
  usPathComposed,
} from "@/data/construction-sand-extraction-and-trade-2026-data";

// viz-types: extractor bars, region donut, US composed volume+price, importer bars, partner pie, dependence scatter, corridor bars | layout: default

type ViewId = "extractors" | "importers" | "city" | "uspath";
type ExtractorLens = "all" | "disclosed" | "mfa";
type ImporterMode = "tonnage" | "city" | "all";

const SAND = "#b45309";
const NAVY = "#0f172a";
const TEAL = "#0f766e";
const SLATE = "#64748b";
const PIE_COLORS = ["#b45309", "#0f766e", "#0369a1", "#7c3aed", "#be123c", "#64748b"];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

