                  <Tooltip
                    formatter={(v) => fmtPct(Number(v), 1)}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "importers" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="HS 2505.90 natural sand imports (2023)"
            subtitle="UN Comtrade / WITS quantity reporters ?? Mt"
          >
            <div className="h-96">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={importers} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={92}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => `${Number(v).toFixed(2)} Mt`}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Bar dataKey="mt" radius={[0, 4, 4, 0]}>
                    {importers.map((row) => (
                      <Cell
                        key={row.name}
                        fill={row.cityState ? SAND : TEAL}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Singapore partner mix (2023)"
            subtitle="Nearly all disclosed tonnage from Malaysia"
          >
            <div className="h-96">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={partners}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={110}
                    label={({ name, value }) =>
                      Number(value) > 1 ? `${name} ${fmtPct(Number(value), 0)}` : ""
                    }
                  >
                    {partners.map((_, i) => (
                      <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v) => fmtPct(Number(v), 2)}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "city" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="City-state fill dependence"
            subtitle="X = disclosed 2023 import Mt (log-ish scale) ?? Y = desk dependence score"
          >
            <div className="h-96">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, right: 12 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Import Mt"
                    scale="log"
                    domain={[0.001, 40]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Import Mt (log)",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Dependence"
                    domain={[60, 100]}
                    tick={{ fontSize: 11 }}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 280]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) =>
                      name === "x"
                        ? `${Number(v).toFixed(2)} Mt`
                        : name === "y"
                          ? `score ${v}`
                          : v
                    }
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? ""
                    }
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Scatter data={scatter} fill={SAND}>
                    {scatter.map((p) => (
                      <Cell key={p.id} fill={p.id === "sg" ? SAND : TEAL} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Fill / cross-border corridor intensity"
            subtitle="Analytical scores ?? not official trade weights"
          >
            <div className="h-96">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={corridors}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 10 }} interval={0} angle={-18} textAnchor="end" height={56} />
                  <YAxis tick={{ fontSize: 11 }} domain={[0, 100]} />
                  <Tooltip contentStyle={{ fontSize: 12 }} />
                  <Bar dataKey="intensity" fill={NAVY} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "uspath" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="US construction sand & gravel (USGS MCS)"
            subtitle="Sold or used by producers ?? Mt + average unit value ($/t)"
          >
            <div className="h-96">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={usPath}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    domain={[800, 1000]}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                    domain={[10, 16]}
                  />
                  <Tooltip contentStyle={{ fontSize: 12 }} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="mt"
                    name="Mt sold/used"
                    fill="#fef3c7"
                    stroke={SAND}
                    strokeWidth={2}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="priceProxy"
                    name="$/t unit value"
                    stroke={TEAL}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="US end-use mix (2025e)"
            subtitle="USGS MCS construction sand & gravel"
          >
            <div className="h-96">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={endUse}
                    dataKey="sharePct"
                    nameKey="label"
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={105}
                    paddingAngle={2}
                  >
                    {endUse.map((_, i) => (
                      <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v) => fmtPct(Number(v), 0)}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Legend wrapperStyle={{ fontSize: 11 }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

